// Abort BEFORE burning a partial episode — an episode renders every scene (💸).
// Mirrors MIN_TOKEN_BALANCE=2000 in show/OnThisDay/show.env.
// Doubles as the config preflight, so an unfilled Show config fails here in
// seconds — not after the story step.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty — set it to a campaign id the API credential\'s account owns');
if (!cfg.userId) throw new Error('Show config: userId is empty — set it to the YakYak user id the API credential belongs to');
const user = $json;
if (user.tokenBalance === undefined) throw new Error('could not fetch the user record — check Show config userId and the "YakYak API" credential (' + (user.error?.message || 'no tokenBalance in response') + ')');
const balance = Number(user.tokenBalance || 0);
const min = Number(cfg.minTokenBalance || 2000);
if (balance < min) throw new Error('token balance ' + balance + ' is below the ' + min + ' minimum — top up before generating an episode');
return [{ json: { balance } }];

// Deterministic date -> anniversary selection — port of show/OnThisDay/compute.js.
// One difference: same-date entries rotate by YEAR here (stateless), where the
// showrunner rotates by story-file count — successive years still get different
// entries for the same calendar date. If today's MM-DD has no entry, walk
// forward day by day (wrapping at year end) to the next date that does.
const corpus = String($json.data || '');
const entries = corpus
  .split(/^## /m)
  .slice(1)
  .map((b) => {
    const nl = b.indexOf('\n');
    const header = b.slice(0, nl).trim(); // "06-09 — 0068 — The Emperor Nero dies, ..."
    const body = b.slice(nl + 1).trim().split(/\n\s*\n/)[0].trim();
    const hm = /^(\d{2}-\d{2})\s*[—-]\s*(\S+)\s*[—-]\s*(.+)$/.exec(header);
    if (!hm) return null;
    return { date: hm[1], year: hm[2], title: hm[3].trim(), account: body };
  })
  .filter(Boolean);
if (!entries.length) throw new Error('no entries parsed from the corpus — check Show config corpusUrl');
const now = new Date();
const pad = (x) => String(x).padStart(2, '0');
const mmdd = pad(now.getUTCMonth() + 1) + '-' + pad(now.getUTCDate());
const entriesFor = (d) => entries.filter((e) => e.date === d);
const advance = (d) => {
  // step one day forward, wrapping Dec 31 -> Jan 01; fixed leap year (2000) so
  // 02-29 is reachable and the cycle length is 366
  const [mm, dd] = d.split('-').map(Number);
  const x = new Date(Date.UTC(2000, mm - 1, dd));
  x.setUTCDate(x.getUTCDate() + 1);
  return pad(x.getUTCMonth() + 1) + '-' + pad(x.getUTCDate());
};
let date = mmdd, matches = entriesFor(date), walked = 0;
while (!matches.length && walked < 366) { date = advance(date); matches = entriesFor(date); walked += 1; }
if (!matches.length) throw new Error('corpus has no usable entries for any date');
const pick = matches[now.getUTCFullYear() % matches.length];
return [{ json: { mmdd, walked, date, year: pick.year, title: pick.title, account: pick.account } }];

const TPL = "You are the head writer for "On This Day", a short-form video series that takes
ONE real historical anniversary and stages it as a self-contained dramatized
reenactment. Educational and cinematic: a true event from the public-domain
historical record, brought to life and framed for a modern audience.

TODAY'S ANNIVERSARY (date {{DATE}}, year {{YEAR}}):
  {{TITLE}}

THE FACTUAL ACCOUNT (your source of truth — do not contradict it, do not invent
fictional outcomes; you may dramatize dialogue and atmosphere around these facts):
  {{ACCOUNT}}

CAST:
  - The Chronicler — the recurring host of the series, a calm, erudite time-traveling
    narrator who steps through eras unseen. MUST be the leading character in Scene 1
    (a cold open that places us at the date and stakes) and the final scene (a close
    that delivers the "On this day…" takeaway as a screenshot caption card). Grave,
    warm, documentary gravitas — think a master narrator.
  - The historical figures of THIS event (e.g. the people named or implied in the
    account). Introduce them by name as the leading character of the middle scenes.
    These change every episode; that is the format. Keep them historically plausible.

TONE: Cinematic historical documentary-drama. Sepia/archival turning to vivid color;
period-accurate detail; real stakes. Educational but dramatic. No glorifying of
violence or atrocity — render tragedy with gravity, not spectacle. No slurs.

STRUCTURE — exactly 7 scenes:
  1. The Chronicler sets the date and the world on the eve of the event (cold open).
  2–5. The event itself, dramatized through its historical figures: the build-up,
       the turning point, the climax, the immediate aftermath. Give the central
       figure of the event the spotlight scene.
  6. The consequence — why this day still matters.
  7. The Chronicler closes, delivering "On this day in {{YEAR}}…" as the takeaway —
     this is the screenshot caption card.

PER-SCENE REQUIREMENTS:
  - ~200 words of prose describing visuals, action and atmosphere (brief it like a
    director: location, light, period detail, what just happened, what's happening
    now). Lean on the archival-to-color look: aged sepia photography, dust and grain
    resolving into rich cinematic color on the dramatic beats.
  - Exactly ONE spoken dialog line per scene, 8–14 words, attributed to the leading
    character. Make it land. Do NOT end the dialog line with a period ("!" or "?" are fine).
  - The leading character of scenes 2–5 must be a historical figure of this event;
    scenes 1 and 7 are The Chronicler.

OUTPUT — reply with ONLY the markdown document below — no preamble, no
triple-backtick fences, nothing after it:

  # On This Day — {{TITLE}}
  **Generated (UTC):** {{TS}}
  **Anniversary:** {{DATE}} {{YEAR}} — {{TITLE}}

  ## Social title: <punchy title for social posting, 50 characters MAX>

  ## Headlines we drew from:
  - On this day in {{YEAR}}: {{TITLE}}

  ## Scene 1 — <short title>
  **Leading character:** The Chronicler
  **Dialog:** "<8–14 word line>"

  <~200 words of scene prose>

  ... (continue through Scene 7, which is again The Chronicler) ...";

// The On This Day head-writer prompt, adapted from show/OnThisDay/compute.js.
// One change vs the showrunner original: the file-write OUTPUT step becomes
// "reply with only the markdown", plus a requested '## Social title:' line so
// ONE model call covers both the story and the ≤50-char social title.
const ts = new Date().toISOString();
const p = $json;
const fill = (t, map) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (map[k] === undefined ? m : map[k]));
const prompt = fill(TPL, { TS: ts, DATE: p.date, YEAR: p.year, TITLE: p.title, ACCOUNT: p.account });
return [{ json: { prompt } }];

// Extract the story markdown from the Claude response, then port of
// storyToDescription() from show/showrunner/story-format.js: drop everything
// before the first '## Scene', collapse each scene's prose to one line, append
// `<Char> says: "<dialog>"`, mapping names through the cast map (CAST_ALIASES
// in show/OnThisDay/show.env).
const resp = $json;
if (resp.stop_reason === 'refusal') throw new Error('Claude declined the request (stop_reason: refusal)');
const story = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
if (!/## Scene/.test(story)) throw new Error('Claude response contains no "## Scene" blocks — not a story');

// ≤50-char social title from the requested '## Social title:' line
let socialTitle = '';
const mTitle = story.match(/^##\s*Social title:\s*(.+)$/mi);
if (mTitle) socialTitle = [...mTitle[1].trim().replace(/^"|"$/g, '')].slice(0, 50).join('');

// caption from the headlines bullets
const capLines = [];
const hm = story.match(/## Headlines we drew from:\n([\s\S]*?)\n##/);
if (hm) for (const l of hm[1].split('\n')) { const t = l.replace(/^-\s*/, '').trim(); if (t) capLines.push(t); }
const socialCaption = capLines.slice(0, 6).join(' · ').slice(0, 400);

const ALIASES = {"The Chronicler":"The Chronicler"};
const mapShort = (name) => { for (const k of Object.keys(ALIASES)) if (name.includes(k)) return ALIASES[k]; return String(name).trim(); };

const lines = story.split(/\r?\n/);
let inScene = false, n = 0, prose = '', character = '', dialog = '';
const parts = [];
const emit = () => {
  if (!inScene) return;
  const p = prose.replace(/[ \t]+/g, ' ').trim();
  const s = mapShort(character);
  parts.push(n === 0 ? '- ' + p + ' ' + s + ' says: "' + dialog + '"' : '\n\n  - ' + p + ' ' + s + ' says: "' + dialog + '"');
  n++;
};
for (const line of lines) {
  if (/^## Scene/.test(line)) { emit(); inScene = true; prose = ''; character = ''; dialog = ''; continue; }
  if (!inScene) continue;
  if (/^\*\*Leading character:\*\*/.test(line)) { character = line.replace(/^\*\*Leading character:\*\*[ \t]*/, ''); continue; }
  if (/^\*\*Dialog:\*\*/.test(line)) { dialog = line.replace(/^\*\*Dialog:\*\*[ \t]*/, '').trim().replace(/^"|"$/g, '').replace(/[.。]$/, ''); continue; }
  if (/^##/.test(line)) { emit(); inScene = false; continue; }
  prose += ' ' + line;
}
emit();
if (!parts.length) throw new Error('no scenes parsed from the story');
const plot = parts.join('');
return [{ json: { plot, socialTitle, socialCaption, scenes: n, story } }];

// Shape the engine call: episode mode in the pinned On This Day campaign, the
// story as the new episode's plot, optional soundtrack pin. The engine's
// sub-workflow trigger is passthrough — this item IS the payload (same shape
// as the engine webhook's body). Re-delivered same-day stories are diff-aware
// on the engine side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, chatWebhookUrl: '' } }];
